def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    seen = set()
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and g[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            r0, r1 = min(y for y, x in cells), max(y for y, x in cells)
            c0, c1 = min(x for y, x in cells), max(x for y, x in cells)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            # Only rectangular, fully closed frames have an interior to decode.
            if not all(g[y][x] == color for y in (r0, r1) for x in range(c0, c1 + 1)):
                continue
            if not all(g[y][x] == color for x in (c0, c1) for y in range(r0, r1 + 1)):
                continue
            interior = [(y, x) for y in range(r0 + 1, r1) for x in range(c0 + 1, c1) if g[y][x] == bg]
            if not interior:
                continue
            ih, iw = r1 - r0 - 1, c1 - c0 - 1
            fill = 2 if ih % 2 == 0 and iw % 2 == 0 else 7
            for y, x in interior:
                g[y][x] = fill
    return g

